        let (prod, mut cons) = endpoints(&ring);
        let mut seen = Vec::new();
        let err = cons
            .reserve_slot_wait::<Msg>(|attempt| {
                seen.push(attempt);
                attempt < 2
            })
            .err();
        assert_eq!(err, Some(Empty));
        assert_eq!(seen, [0, 1, 2]);
        send(&prod, 0, 2);
        let mut seen = Vec::new();
        let err = prod
            .send_wait::<Msg>(
                |attempt| {
